"""Actual public step attachments and native JSON/JUnit/HTML provenance."""
import argparse,json,pathlib,subprocess,tempfile,xml.etree.ElementTree as ET
p=argparse.ArgumentParser();p.add_argument('--executable',required=True,type=pathlib.Path);p.add_argument('--sdk-directory',required=True,type=pathlib.Path);p.add_argument('--directory',required=True,type=pathlib.Path);p.add_argument('--node',required=True);a=p.parse_args();receipt=a.directory.resolve();receipt.mkdir(parents=True,exist_ok=True);out=pathlib.Path(tempfile.mkdtemp(prefix='cases-',dir=receipt));sdk=a.sdk_directory.resolve();rows=[]
common="import{defineNativeSuite}from "+json.dumps((sdk/'native.js').as_uri())+";import{strict as assert}from'node:assert';import{writeFileSync}from'node:fs';"
def run(name,source,code=0):
 root=out/name;root.mkdir();suite=root/'suite.mjs';suite.write_text(common+source);v=subprocess.run([str(a.executable),'--node',a.node,'--host-script',str(sdk/'native-runner-host.js'),'--suite',str(suite),'--report',str(root/'actual.json'),'--junit',str(root/'actual.xml'),'--html',str(root/'actual.html')],capture_output=True,timeout=15);(root/'stdout.bin').write_bytes(v.stdout);(root/'stderr.bin').write_bytes(v.stderr);assert v.returncode==code and not v.stderr,(name,v.returncode,v.stdout,v.stderr);r=json.loads((root/'actual.json').read_text());steps={s['id']:s for s in r['steps']};xml=ET.parse(root/'actual.xml');props={x.attrib['name']:x.attrib.get('value','')for x in xml.findall('.//property')};html=(root/'actual.html').read_text()
 for artifact in r['attachments']:
  assert pathlib.Path(artifact['path']).is_file()and artifact['writerExitConfirmed']and artifact['writerExitCode']==0
  if'stepId'in artifact:
   step=steps[artifact['stepId']];assert all(step[k]==artifact[k]for k in['testId','generation','callbackToken','scopeId','scopeGeneration','workerIndex','pid']);assert step['startedMonotonicMs']<=artifact['startedMonotonicMs']<=artifact['writerExitReceiptMonotonicMs']<=step['receiptMonotonicMs'];assert props['native.attachment'+artifact['id']+'.stepId']==step['id'];assert 'data-attachment-id="'+artifact['id']+'" data-step-id="'+step['id']+'"'in html
 rows.append({'scope':name,'actualExitCode':v.returncode,'report':str(root/'actual.json')});return root,r
root,v=run('actual-body-nested-step-and-outer-attachment-compatibility',"export default defineNativeSuite({tests:[{title:'actual native step files',run:async(_,i)=>{await i.attach('outer',{body:'outer remains outer'});const value=await i.step('parent',async s=>{await s.attach('parent-file',{body:new Uint8Array([0,1,128,255])});await i.step('child',async child=>{assert.equal(child.parentId,s.id);await child.attach('child-file',{body:'actual child bytes'})});return 17});assert.equal(value,17)}}]});");assert v['summary']['expected']==1 and len(v['steps'])==2 and len(v['attachments'])==3;outer=next(x for x in v['attachments']if x['name']=='outer');assert'stepId'not in outer;parent=next(s for s in v['steps']if s['title']=='parent');child=next(s for s in v['steps']if s['title']=='child');assert child['parentId']==parent['id'];assert pathlib.Path(next(x for x in v['attachments']if x['name']=='parent-file')['path']).read_bytes()==bytes([0,1,128,255])
root,v=run('actual-all-and-each-hook-step-files',"const hook=kind=>({run:async(_,i)=>{await i.step(kind,async s=>{await s.attach(kind,{body:'actual '+kind})})}});export default defineNativeSuite({hooks:{beforeAll:[hook('beforeAll')],beforeEach:[hook('beforeEach')],afterEach:[hook('afterEach')],afterAll:[hook('afterAll')]},tests:[{title:'actual hook scope files',run:()=>{}}]});");assert v['summary']['expected']==1 and len(v['attachments'])==4 and {x['callbackKind']for x in v['attachments']}=={'beforeAll','beforeEach','afterEach','afterAll'}
root,v=run('void-step-file-retains-real-file-fence-after-raw-return',"export default defineNativeSuite({tests:[{title:'actual unawaited native file',run:async(_,i)=>{await i.step('actual pending file',s=>{void s.attach('actual bytes',{body:new Uint8Array(65536).fill(231)})})}}]});");step=v['steps'][0];artifact=v['attachments'][0];assert step['status']=='passed'and step['callbackReceiptOK']and step['callbackReceiptMonotonicMs']<=artifact['writerExitReceiptMonotonicMs']<=step['receiptMonotonicMs'];assert pathlib.Path(artifact['path']).read_bytes()==bytes([231])*65536
source=out/'actual-input.bin';source.write_bytes(bytes(range(256)));root,v=run('actual-native-path-copy-has-step-owner',"export default defineNativeSuite({tests:[{title:'actual native copy',run:(_,i)=>i.step('copy',s=>s.attach('path',{path:"+json.dumps(str(source))+"}))}]});");assert v['attachments'][0]['sourceKind']=='path'and pathlib.Path(v['attachments'][0]['path']).read_bytes()==bytes(range(256))
root,v=run('caught-real-native-filesystem-error-does-not-fail-raw-step',"export default defineNativeSuite({tests:[{title:'actual caught file error',run:(_,i)=>i.step('caught',async s=>{await assert.rejects(s.attach('missing',{path:''}),/errno=2/)})}]});");assert v['steps'][0]['status']=='passed'and not v['attachments']and not v['globalErrors']
root,v=run('pending-real-file-error-after-raw-success-fails-native-step',"export default defineNativeSuite({tests:[{title:'actual file fence failure',run:async(_,i)=>{await assert.rejects(i.step('pending error',s=>{void s.attach('missing',{path:''}).catch(()=>{})}),/errno=2/)}}]});");assert v['summary']['expected']==1 and v['steps'][0]['status']=='failed'and v['steps'][0]['callbackReceiptOK']and 'errno=2'in v['steps'][0]['attachmentError']and not v['attachments']
root,v=run('stale-step-attachment-closure-rejects-after-native-receipt',"export default defineNativeSuite({tests:[{title:'actual stale step info',run:async(_,i)=>{let actual;await i.step('completed',s=>{actual=s});await assert.rejects(async()=>actual.attach('stale',{body:'must not exist'}),/no longer active/)}}]});");assert v['steps'][0]['status']=='passed'and not v['attachments']and not v['globalErrors']
root,v=run('pending-local-step-skip-has-authenticated-native-file-cancellation',"export default defineNativeSuite({tests:[{title:'actual supported local cause',run:async(_,i)=>{await i.step('pending local skip',s=>{void s.attach('pending',{body:'actual'});s.skip('actual accepted local file cause')})}}]});");assert v['summary']['expected']==1 and v['steps'][0]['status']=='skipped'and v['steps'][0]['stepSkip']['reason']=='actual accepted local file cause'and not v['attachments']and not v['globalErrors']
root,v=run('accepted-test-skip-cancels-actual-step-file-with-real-cause',"export default defineNativeSuite({tests:[{title:'actual accepted test cause',run:(_,i)=>i.step('actual skipped step',async s=>{const file=s.attach('pending',{body:'actual bytes'});try{i.skip('actual test cause\\ud800')}finally{await assert.rejects(file)}})}]});");assert v['attempts'][0]['status']=='skipped'and v['attempts'][0]['expected']and v['steps'][0]['status']=='skipped'and v['steps'][0]['testSkip']['reason']=='actual test cause\ud800'and not v['attachments']and not v['globalErrors']
root,v=run('real-thrown-value-and-completed-step-file-both-retained',"export default defineNativeSuite({tests:[{title:'actual author error identity',run:async(_,i)=>{const actual=new Error('actual author error');await assert.rejects(i.step('real error',async s=>{await s.attach('retained',{body:'actual retained bytes'});throw actual}),error=>error===actual)}}]});");assert v['steps'][0]['status']=='failed'and not v['steps'][0]['callbackReceiptOK']and len(v['attachments'])==1 and pathlib.Path(v['attachments'][0]['path']).read_bytes()==b'actual retained bytes'
root,v=run('accepted-beforeEach-skip-cancels-native-step-file-before-cleanup',"let cleaned=false;export default defineNativeSuite({hooks:{beforeEach:[{run:(_,i)=>i.step('hook skip',async s=>{const file=s.attach('pending',{body:'actual hook bytes'});try{i.skip('actual beforeEach step cause')}finally{await assert.rejects(file);cleaned=true}})}],afterEach:[{run:()=>assert(cleaned,'actual raw/file cleanup precedes afterEach')}]},tests:[{title:'actual skipped hook',run:()=>assert.fail('body must not run')}]});");assert v['attempts'][0]['status']=='skipped'and v['attempts'][0]['expected']and v['steps'][0]['status']=='skipped'and v['steps'][0]['callbackKind']=='beforeEach'and v['steps'][0]['testSkip']['reason']=='actual beforeEach step cause'and not v['attachments']and not v['globalErrors']
root,v=run('actual-retry-keeps-step-file-owner-generation-and-worker',"export default defineNativeSuite({tests:[{title:'actual retry file',retries:1,run:(_,i)=>i.step('retry step '+i.retry,async s=>{await s.attach('retry '+i.retry,{body:'actual retry '+i.retry});if(!i.retry)throw Error('actual first attempt failure')})}]});");assert len(v['attempts'])==2 and v['summary']['flaky']==1 and len(v['steps'])==2 and len(v['attachments'])==2 and len({f['generation']for f in v['attachments']})==2 and len({f['pid']for f in v['attachments']})==2 and [s['status']for s in v['steps']]==['failed','passed']
(receipt/'report.json').write_text(json.dumps({'passed':len(rows),'scope':'Actual native StepInfo.attach callback/step/file ownership, actual JSON/XML/HTML refs and raw-vs-joint receipts. Local-step and test-skip are distinct typed native cancellation causes. No upstream full reporter parity claim.','groups':rows},indent=2)+'\n');print('PASS',len(rows),'actual native step attachment public/report groups')
